package com.riverguard.v2;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import java.time.Instant;
import static org.junit.Assert.*;
import static com.riverguard.v2.PhoneValidation.*;
public class RepairRegressionTest {
    private static final long NOW=1792641600000L;
    private JSONObject row(String sample,double height,int revision) {
        JSONObject settings=json("enabled",json("ph",true,"turbidity",true,"temperature",true,"water_level",true),"ph",new JSONArray().put(json("mv",1500,"value",4)).put(json("mv",2000,"value",7)),"turbidity",new JSONArray().put(json("mv",1500,"value",100)).put(json("mv",2500,"value",0)),"level",json("reference",200,"minimum",25,"maximum",450),"temperature_offset",0,"verified",true);
        return json("id",1,"deviceId","one","timestamp",Instant.ofEpochMilli(NOW).toString(),"receivedAt",Instant.ofEpochMilli(NOW).toString(),"payload",json("sample_id",sample,"config_revision",revision,"raw",json("ph_mv",2000,"turbidity_mv",2400,"temperature_c",27,"distance_cm",200-height),"sensor_health",new JSONObject()),"settings",settings);
    }
    private JSONObject evaluation(JSONObject row){return SignalEvaluator.evaluate(new JSONArray().put(row),WatchPolicy.defaults(),NOW);}
    @Test public void missingProbeCannotRecoverActiveWarning(){JSONObject state=AlertLedger.apply(null,evaluation(row("high",120,1)),NOW).optJSONObject("state");for(int i=0;i<5;i++){JSONObject missing=row("missing"+i,40,1);put(missing.optJSONObject("payload").optJSONObject("sensor_health"),"water_level","timeout");JSONObject result=AlertLedger.apply(state,evaluation(missing),NOW+i);state=result.optJSONObject("state");for(int j=0;j<result.optJSONArray("events").length();j++)assertNotEquals("recovered",result.optJSONArray("events").optJSONObject(j).optString("phase"));}assertTrue(state.optJSONObject("conditions").optJSONObject("water_warning").optBoolean("active"));}
    @Test public void changedCalibrationOrPolicyCannotClaimMeasuredRecovery(){for(boolean calibration:new boolean[]{true,false}){JSONObject state=AlertLedger.apply(null,evaluation(row("high",120,1)),NOW).optJSONObject("state");for(int i=0;i<4;i++){JSONObject clear=evaluation(row("clear"+i,40,calibration?2:1));if(!calibration)put(clear,"segment","different-policy");JSONObject result=AlertLedger.apply(state,clear,NOW+i);state=result.optJSONObject("state");for(int j=0;j<result.optJSONArray("events").length();j++)assertNotEquals("recovered",result.optJSONArray("events").optJSONObject(j).optString("phase"));}assertFalse(state.optJSONObject("conditions").optJSONObject("water_warning").optBoolean("active"));}}
    @Test public void threePositiveSamplesRecoverButDuplicateAndMissingResetCounter(){JSONObject state=AlertLedger.apply(null,evaluation(row("high",120,1)),NOW).optJSONObject("state");JSONObject clear=evaluation(row("a",40,1));state=AlertLedger.apply(state,clear,NOW).optJSONObject("state");state=AlertLedger.apply(state,clear,NOW).optJSONObject("state");assertEquals(1,state.optJSONObject("conditions").optJSONObject("water_warning").optInt("clearCount"));JSONObject missing=row("fault",40,1);put(missing.optJSONObject("payload").optJSONObject("sensor_health"),"water_level","timeout");state=AlertLedger.apply(state,evaluation(missing),NOW).optJSONObject("state");assertEquals(0,state.optJSONObject("conditions").optJSONObject("water_warning").optInt("clearCount"));for(int i=0;i<3;i++)state=AlertLedger.apply(state,evaluation(row("b"+i,40,1)),NOW).optJSONObject("state");assertFalse(state.optJSONObject("conditions").optJSONObject("water_warning").optBoolean("active"));}
    @Test public void escalationDoesNotRecoverWatch(){JSONObject high=evaluation(row("high",120,1));assertEquals("unknown",high.optJSONObject("evidence").optString("water_watch"));}
    @Test public void incompleteRiseIsUnknown(){assertEquals("unknown",evaluation(row("one",40,1)).optJSONObject("evidence").optString("water_rise"));}
    @Test public void missingOrImpossibleGeometryIsNotCommissionable(){JSONObject cfg=defaults();assertFalse(WatchPolicy.valid("esp32",WatchPolicy.defaults(),cfg,false));put(cfg,"level",json("reference",50,"minimum",25,"maximum",450));assertFalse(WatchPolicy.valid("esp32",WatchPolicy.defaults(),cfg,false));assertTrue(WatchPolicy.valid("esp32",json("elevated",10,"warning",20,"rise_limit",10),cfg,false));assertFalse(WatchPolicy.valid("esp32",json("elevated",10,"warning",20,"rise_limit",10),cfg,true));assertTrue(WatchPolicy.valid("simulation",WatchPolicy.defaults(),null,false));}
    @Test public void allDemoScenariosRemainValidAfterLongRuntime(){for(String scenario:DemoState.SCENARIOS)for(long step:new long[]{0,10,119,120,249,4978,Integer.MAX_VALUE,Long.MAX_VALUE}){JSONObject p=DemoState.sample(scenario,step,NOW);assertNotNull(PhoneValidation.demo(p));assertTrue(p.optDouble("water_level")<=150);assertTrue(p.optDouble("turbidity")<=250);}}
    @Test public void draftsAllowUnfinishedNumbersButRejectMalformedShapes(){JSONObject cfg=defaults();put(cfg,"temperature_offset",null);PhoneValidation.draft(json("revision",0,"settings",cfg));put(cfg,"enabled",null);try{PhoneValidation.draft(json("revision",0,"settings",cfg));fail();}catch(Problem expected){assertEquals(422,expected.status);}}
    @Test public void fractionalLedgerValuesAreCorrupt(){assertFalse(AlertLedger.validState(json("conditions",json("water_warning",json("active",true,"level",2.5,"clearCount",0)))));}
    @Test public void hugeNumericInputIsValidationFailure(){String huge=new String(new char[1000]).replace('\0','9');try{number(object("{\"n\":"+huge+"}"),"n",0,1000);fail();}catch(Problem expected){assertEquals(422,expected.status);}}
    @Test public void policyChangeRefreshesStillActiveWarningDeliveryEvidence(){JSONObject initial=evaluation(row("high",120,1));JSONObject state=AlertLedger.apply(null,initial,NOW).optJSONObject("state");JSONObject changed=evaluation(row("next",120,1));put(changed,"segment","changed-policy");JSONObject result=AlertLedger.apply(state,changed,NOW);boolean changedEvent=false,activeEvent=false;for(int i=0;i<result.optJSONArray("events").length();i++){JSONObject e=result.optJSONArray("events").optJSONObject(i);changedEvent|="settings_changed".equals(e.optString("phase"));activeEvent|="active".equals(e.optString("phase"))&&"water_warning".equals(e.optString("kind"));}assertTrue(changedEvent);assertTrue(activeEvent);}
    @Test public void continuingHighAfterPolicyChangeResolvesAsRechecked(){JSONObject state=AlertLedger.apply(null,evaluation(row("a",120,1)),NOW).optJSONObject("state");JSONObject high=evaluation(row("b",120,1));put(high,"segment","updated");state=AlertLedger.apply(state,high,NOW).optJSONObject("state");assertTrue(state.optJSONObject("conditions").optJSONObject("water_warning").optBoolean("recheck"));String phase="";for(int i=0;i<3;i++){JSONObject clear=evaluation(row("clear"+i,40,1));put(clear,"segment","updated");JSONObject transition=AlertLedger.apply(state,clear,NOW);state=transition.optJSONObject("state");for(int j=0;j<transition.optJSONArray("events").length();j++){JSONObject event=transition.optJSONArray("events").optJSONObject(j);if(event.optString("kind").equals("water_warning"))phase=event.optString("phase");}}assertEquals("rechecked",phase);}
    @Test public void firstConnectionWarningRecoversAfterThreeValidPackets(){JSONObject missing=json("signals",new JSONArray().put(json("kind","connection","level",1,"title","No first sample","detail","Waiting")),"evidence",json("connection","active"),"sample","","fresh",false,"segment","no-readings:1");JSONObject state=AlertLedger.apply(null,missing,NOW).optJSONObject("state");for(int i=0;i<3;i++)state=AlertLedger.apply(state,evaluation(row("first"+i,40,1)),NOW).optJSONObject("state");assertFalse(state.optJSONObject("conditions").optJSONObject("connection").optBoolean("active"));}
    @Test public void eventsRetainMeasurementAndPolicyEvidence(){JSONObject e=evaluation(row("boot-001",120,1));put(e,"watchRevision",3);put(e,"watchSettings",WatchPolicy.defaults());JSONObject event=AlertLedger.apply(null,e,NOW).optJSONArray("events").optJSONObject(0);assertEquals("boot-001",event.optString("sample"));assertEquals(Instant.ofEpochMilli(NOW).toString(),event.optString("measuredAt"));assertEquals(3,event.optInt("watchRevision"));assertNotNull(event.optJSONObject("watchSettings"));}
}
